TESTDATA["pet3-t4"] = {"title": "Cambridge PET 3 · Test 4", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Mr Johnstone will unfortunately be unable to teach Class 9.2 today.", "Class 9.2 should get on with some unfinished work for part of the lesson.", "Students who arrive late to Mr Johnstone’s class must tell the office."], "answer": "B"}, {"n": 2, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["It is essential to bring an identity card to the port.", "This entrance is to be used only by people with identity cards.", "To visit this area, go to the main entrance for an identity card."], "answer": "C"}, {"n": 3, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Do not climb the walls as they are dangerous.", "There is a danger of falling on to the stones.", "Check for loose stones before you climb."], "answer": "A"}, {"n": 4, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["A £10 fine will be payable later if you travel without a ticket.", "If you lose your ticket, a new one will cost you £10.", "You are fined £10 at once if you can’t show us your ticket."], "answer": "C"}, {"n": 5, "text": "", "img": "data:image/jpeg;base64,", "q": "How should Mustafa reply to his brother?", "options": ["by email", "by phone", "by letter"], "answer": "B"}]}, {"part": 2, "people": [{"n": 6, "name": "Pedro and his two friends", "text": "Pedro and his two friends want to spend some time in a seaside town where they can do water sports and be taught how to sail a boat properly.", "answer": "D"}, {"n": 7, "name": "Adriana and Claire", "text": "Adriana and Claire want lots of entertainment in the evening after they have spent all day relaxing on the beach. Adriana enjoys dancing and Claire wants to see some of the latest films.", "answer": "F"}, {"n": 8, "name": "Pete and Elizabeth", "text": "Pete and Elizabeth have five-year-old twin boys who are learning to swim. They want somewhere with a good beach and plenty of activities for the children to do if the weather is bad.", "answer": "H"}, {"n": 9, "name": "Maria", "text": "Maria enjoys going for long walks on holiday, as well as listening to music and eating good food. She prefers old-fashioned seaside places where she can really relax.", "answer": "A"}, {"n": 10, "name": "Susanna and Bryan", "text": "Susanna and Bryan and their nine-year-old son, Simon, want to go camping in a traditional seaside town, away from too many people. Simon is very interested in history.", "answer": "E"}], "texts": [{"letter": "A", "title": "Ashton", "text": "A small old-fashioned town close to the stony beach where the fishermen still sell their fish every morning. There is a small cinema and popular classical concerts are held every Saturday in the Town Hall. The East Coast long-distance path passes nearby."}, {"letter": "B", "title": "Hensham-on-Sea", "text": "A quiet seaside town of narrow streets and small shops. There are two steam railways, one of which goes to and from the beach. Hire a boat on the small lake or go for long walks through the pinewoods."}, {"letter": "C", "title": "Brightsea", "text": "Once a fishing town, Brightsea is now a yachting centre with the best sailing on the East Coast. There are excellent walks along the river which give visitors the chance to study the birdlife in this area. Good campsite."}, {"letter": "D", "title": "Whitecliff", "text": "A popular seaside town with lots of outside activities for everyone. The beach is a mixture of sand and small stones and visitors here have the opportunity to try windsurfing. For the very keen, there are sailing courses all the year round at the Hillstowe Sailing Club."}, {"letter": "E", "title": "Northgate", "text": "This is an attractive old town standing on the cliff top overlooking the sea. Winner of the Good Beach and Campsite prize and famous for its pleasant old streets and fishermen’s cottages. Visit the local museum of 19th-century life."}, {"letter": "F", "title": "Derringham", "text": "An old fishing port which has grown into a busy holiday town. There are good beaches but swimming is dangerous at certain times of the day. There are plenty of indoor facilities, from museums to discos and cinemas."}, {"letter": "G", "title": "Alton Sands", "text": "A successful combination of holiday centre and fishing port. The South Beach is particularly clean and well kept. It’s possible to hire a sailing or rowing boat for the day here. Outdoor swimming pools and tennis courts make this town an ideal place to spend your holiday."}, {"letter": "H", "title": "Kingsbridge", "text": "This is one of Britain’s most popular seaside towns. It has wide, sandy beaches and a prize-winning Marina Leisure Centre which offers a large variety of all-weather sports, including a new swimming pool. The town has beautiful gardens along the seafront and there are interesting museums and many places to explore."}]}, {"part": 3, "title": "Sunningdale Hotel", "text": "ACCOMMODATION\nNear the town centre – Single rooms available: French, German, Spanish and Russian spoken\n£200 per week single room or £36 per day with English breakfast and dinner. Double room £160 each person per week, £33 daily. Half price for children under 14.\n\nThe Sunningdale Hotel was built in 1913 and opened by Princess Louise. It has provided excellent service for people from all over the world and people of all ages and nationalities have stayed here. During the past 80 years over 50,000 guests from 174 different countries have visited Sunningdale.\n\nThe hotel is on one of the main roads leading to the town centre. It is about 20 minutes by bus from the centre of town and buses to many other parts of the town stop outside the hotel. Guests should be careful not to travel on buses with the blue sign Express on the front because they do not stop near our hotel. An underground station is less than 100 metres away.\n\nThe main building has 200 well-furnished, centrally-heated single rooms, each fitted with hot and cold water basins. Showers, baths and toilets are at the end of all corridors. The hotel has a shop, sitting rooms, four television rooms, table tennis room, library and laundry. There are also eight pianos available for guests’ use. There are spaces to park cars in the hotel drive.\n\nDaily newspapers are provided free and stamps can be bought at the office. Guests who stay for long periods must pay for their accommodation weekly in advance and one week’s notice is required for departures. Short or long term guests are welcome but long term guests are offered rooms first.\n\nMeal times are: breakfast 7 am–9.30 am; lunch 1 pm–2 pm; dinner 5.30 pm–7 pm. During the week, for those studying or working late, dinner can be requested until 11 pm by writing your name on the late list or by telephoning before 7 pm. A selection of 10 menu choices are available for breakfast and dinner.\n\nNo animals of any description or fires of any type (either for heating food or heating the room) are allowed, and guests are requested to respect the comfort of others. If you have tapes or CDs, please try to keep the noise level down to a minimum, especially between the hours of 11 pm and 8 am.\n\nGuests are advised to use taxis to get to the hotel if they arrive by train because we are some distance from the main railway station.", "items": [{"n": 11, "q": "Food is included in the cost of a room.", "answer": "A"}, {"n": 12, "q": "A princess used to live in the building.", "answer": "B"}, {"n": 13, "q": "Sunningdale Hotel is on a quiet road.", "answer": "B"}, {"n": 14, "q": "An Express bus will take you from the hotel to the centre of town.", "answer": "B"}, {"n": 15, "q": "The hotel provides facilities for washing clothes.", "answer": "A"}, {"n": 16, "q": "The hotel prefers guests who stay for a short time.", "answer": "B"}, {"n": 17, "q": "You can have dinner as late as 11 pm.", "answer": "A"}, {"n": 18, "q": "You are allowed to cook food in your room.", "answer": "B"}, {"n": 19, "q": "You can only play music until 11 pm.", "answer": "B"}, {"n": 20, "q": "It is a long way to walk from the hotel to the main railway station.", "answer": "A"}]}, {"part": 4, "title": "", "text": "To: The Manager of Mezzo Mash Restaurant\n\nDear Sir,\n\nLast Tuesday evening I went with two friends to your restaurant for my 18th birthday. I’d booked the table for eight o’clock and we arrived about ten minutes late, but that was not a problem. The waiter, who was very polite, showed us to our table and we studied the menu. I ordered a fish pie and my friends ordered some salads. However, after about fifteen minutes, the waiter informed us that there was no more fish pie. He apologised and suggested ordering something else. I looked at the menu again and decided to have the same as my friends – a salad.\n\nWhen the food came, it was very good. After we’d finished, we decided to order some desserts. The waiter said that, unfortunately, it was too late. There wasn’t enough time for us to order desserts. He said he was very sorry but our table was reserved by another group at nine thirty and we would have to leave.\n\nWe paid the bill and left feeling very disappointed. It spoilt my birthday. Nobody told us when we arrived that there was a time limit. It was very unsatisfactory and I doubt that we’ll go to your restaurant again.\n\nYours faithfully,\nMartin Cary", "items": [{"n": 21, "q": "What is Martin Cary trying to do in the letter?", "options": ["make an enquiry", "cancel a booking", "make a complaint", "offer a suggestion"], "answer": "C"}, {"n": 22, "q": "What will the restaurant manager discover from the letter?", "options": ["One of his waiters behaved badly.", "Some customers had a bad experience.", "His food is unsatisfactory.", "He charges too much for the meals."], "answer": "B"}, {"n": 23, "q": "What does Martin think about their experience?", "options": ["They got to the restaurant too late.", "There was not much choice on the menu.", "They won’t return to the restaurant.", "The food took too long to arrive."], "answer": "C"}, {"n": 24, "q": "Martin and his friends couldn’t have any dessert because", "options": ["someone had booked their table.", "they had to be home by 9.30.", "it was too expensive.", "there was none left."], "answer": "A"}, {"n": 25, "q": "What did Martin’s friends say as they left the restaurant?", "options": ["I didn’t like my salad. I wish I’d had fish pie like you.", "Never mind, let’s go and get some ice cream at Rick’s.", "I hope you didn’t leave the waiter a tip – he was so unfriendly.", "It’s a pity there wasn’t enough birthday cake."], "answer": "B"}]}, {"part": 5, "title": "PONY EXPRESS", "text": "Before 1860 there was no quick way of getting mail (0) ……… (between) the east and the west of the United States. There were no railways at that [26] and most mail was sent by coach. It usually [27] at least 25 days for coaches to [28] the coast. So in 1860 it [29] decided to send mail by ‘Pony Express’, which was much faster. Riders [30] very fast horses were placed along the route. They were at [31] distances from each other and the mail was handed from one rider to the next. Riders were all [32] to travel between twenty and thirty kilometres [33] day on very bad roads. At each stop two minutes were [34] for exchanging the mail bags, but riders were often held up by awful weather [35] closed the roads. With the invention of the telegraph in 1861, the demand for Pony Express disappeared.", "gaps": {"26": {"options": ["time", "date", "age", "season"], "answer": "A"}, "27": {"options": ["spent", "lasted", "took", "passed"], "answer": "C"}, "28": {"options": ["get", "arrive", "come", "reach"], "answer": "D"}, "29": {"options": ["had", "was", "has", "is"], "answer": "B"}, "30": {"options": ["for", "off", "with", "behind"], "answer": "C"}, "31": {"options": ["like", "equal", "same", "level"], "answer": "B"}, "32": {"options": ["wished", "wanted", "expected", "hoped"], "answer": "C"}, "33": {"options": ["a", "one", "some", "any"], "answer": "A"}, "34": {"options": ["let", "allowed", "done", "made"], "answer": "B"}, "35": {"options": ["which", "where", "what", "when"], "answer": "A"}}}], "writing": [{"part": 1, "title": "Here are some sentences about a trip to the zoo.", "items": [{"n": 1, "first": "A family ticket costs £10.", "before": "The cost of a family ticket", "after": "£10.", "answers": ["is"]}, {"n": 2, "first": "Entrance at weekends is more expensive than on weekdays.", "before": "Entrance on weekdays is", "after": "than at weekends.", "answers": ["cheaper", "less expensive"]}, {"n": 3, "first": "You don’t have to pay to visit the zoo on Thursdays.", "before": "You can visit the zoo", "after": "paying on Thursdays.", "answers": ["without"]}, {"n": 4, "first": "There aren’t any elephants at the zoo now.", "before": "The zoo doesn’t", "after": "any more.", "answers": ["have elephants", "have any elephants", "keep elephants", "keep any elephants", "own elephants", "own any elephants"]}, {"n": 5, "first": "The new Zoo restaurant has been open for a week.", "before": "The new Zoo restaurant", "after": "last week.", "answers": ["opened", "was opened"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You have just received a present from some friends who live in the USA.\n\nWrite a card to send to your friends. In your card, you should\n• thank them for the present\n• explain why you like it\n• say what you are going to send them in return.\n\nWrite 35–45 words on your answer sheet.", "points": ["ringraziare per il regalo", "dire perché gli/le piace", "dire che cosa manderà in cambio"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "This is part of a letter you receive from your English friend Mark.\n\n“I know I spend too much time watching television! How much television do you watch? What else do you do to relax?”\n\nNow write a letter to Mark, answering his questions.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "You have to write a story for your English teacher.\nYour story must have this title:\n\nA wonderful experience.\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet3-t4-l1.mp3", "items": [{"n": 1, "q": "What time will the flight leave?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 2, "q": "Which is the photo of the girl’s father?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 3, "q": "What must the woman wear at work?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "Where will they sit in the theatre?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 5, "q": "How did the woman cook the onions?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 6, "q": "What will the man buy?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 7, "q": "How will they travel to Edinburgh?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}]}, {"part": 2, "intro": "You will hear someone talking to a group of students about a visit to an Arts Centre.", "audio": "audio/pet3-t4-l2.mp3", "items": [{"n": 8, "q": "There are still tickets for", "options": ["the piano concert.", "Twelfth Night.", "Spider and Rose."], "answer": "C"}, {"n": 9, "q": "The coach will leave at 3.30 because", "options": ["they don’t want to miss the shows.", "they want free time at the Arts Centre.", "it’s a long journey to the Arts Centre."], "answer": "B"}, {"n": 10, "q": "You have to pay to see", "options": ["the Russian ballet exhibition.", "the Scottish jewellery.", "the South American photographs."], "answer": "A"}, {"n": 11, "q": "You can buy clothes", "options": ["on the first floor.", "in the souvenir shop.", "close to the Arts Centre."], "answer": "C"}, {"n": 12, "q": "If you want a snack and a hot drink, try", "options": ["the Fountain.", "Charlie’s.", "the cinema kiosk."], "answer": "B"}, {"n": 13, "q": "Everyone should get back on the coach at", "options": ["10.10.", "10.15.", "10.20."], "answer": "C"}]}, {"part": 3, "intro": "You will hear someone talking about a sports camp for children.", "audio": "audio/pet3-t4-l3.mp3", "notes": "SUNNINGTON SPORTS CAMP\n\nChoice of afternoon activity\nSign list outside [14] room\n\nClothes\nWear track suit, but also bring [15] and a T-shirt\n2 pairs of sports [16]\n\nFood\nLunch served in canteen every half-hour between 12.15 and [17]\nSnack bar sells drinks, chocolate and [18]\n\nCertificate\nMarks given for\nattitude: effort and team-work\nperformance: strength, [19] and skill", "answers": {"14": ["changing room", "the changing room", "changing", "the changing"], "15": ["shorts"], "16": ["shoe", "shoes"], "17": ["1.45"], "18": ["biscuit", "biscuits"], "19": ["speed", "speeds"]}}, {"part": 4, "intro": "You will hear a conversation between a young man, Mike, and his sister, Ann. They are talking about buying a wedding present for some friends of theirs.", "audio": "audio/pet3-t4-l4.mp3", "items": [{"n": 20, "q": "Mike likes to plan ahead more than Ann does.", "answer": "A"}, {"n": 21, "q": "Ann thinks they should buy a useful present.", "answer": "B"}, {"n": 22, "q": "Mike thinks he should choose the present.", "answer": "B"}, {"n": 23, "q": "Mike has known Tony the longest.", "answer": "A"}, {"n": 24, "q": "Mike thinks he will enjoy the wedding.", "answer": "A"}, {"n": 25, "q": "Ann prefers large weddings.", "answer": "B"}]}]};
